{
  "headline": "Voriconazole is not on FDA's shortage list; supply traces to Aurobindo Pharma Limited plant with past OAI and recent VAI inspections",
  "headline_cites": ["D4", "E7", "E5", "E6"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows voriconazole is not listed as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "All three Corvale sites stock the same NDC 65862089103 labeled by Aurobindo Pharma Limited.",
      "cites": ["E1", "E2", "E3"]
    },
    {
      "text": "The product label identifies the manufacturing plant as Aurobindo Pharma Limited (FEI 3007373532) in India.",
      "cites": ["E7"]
    },
    {
      "text": "FDA inspection records for that plant show an OAI classification after an inspection ending 2019-09-27 and a VAI classification after an inspection ending 2022-05-10.",
      "cites": ["E5", "E6"]
    },
    {
      "text": "No FDA shortage posting exists to link those inspections to a current shortage.",
      "cites": ["D4"]
    },
    {
      "text": "Corvale East has 6.3 days of 50 mg tablets on hand; Corvale Lakeside has 26.3 days and can spare 36 tablets while retaining 14 days.",
      "cites": ["D1", "D3", "D5"]
    },
    {
      "text": "The recommended action is to transfer 36 tablets from Corvale Lakeside to Corvale East, raising East to 9 days on hand.",
      "cites": ["D5"]
    }
  ]
}
